from pathlib import Path

path = Path('ClockTimer.js')
text = path.read_text()
start = text.index('        #replaceRangeWithSegments(\n')
end = text.index('        #shiftExistingTimeRanges(\n', start)

replacement = '''        #replaceRangeWithSegments(\n            range,\n            spans\n        ) {\n            const preservedAttributes =\n                this.#getPreservedAttributes(\n                    range\n                );\n\n            const preserveRangeLength =\n                range.hasAttribute(\n                    "range-length"\n                );\n\n            const segments = [];\n\n            for (\n                const [\n                    spanStart,\n                    spanEnd\n                ] of spans\n            ) {\n                if (\n                    !Number.isFinite(spanStart) ||\n                    !Number.isFinite(spanEnd) ||\n                    spanEnd <= spanStart\n                ) {\n                    continue;\n                }\n\n                let cursor =\n                    spanStart;\n\n                while (\n                    cursor < spanEnd\n                ) {\n                    const ringIndex =\n                        this.#getRingIndex(\n                            cursor\n                        );\n\n                    const ringEnd =\n                        this.#getRingStart(\n                            ringIndex\n                        ) +\n                        ClockTimer.#HOUR;\n\n                    const segmentEnd =\n                        Math.min(\n                            spanEnd,\n                            ringEnd\n                        );\n\n                    segments.push({\n                        start: cursor,\n                        end: segmentEnd,\n                        ringIndex\n                    });\n\n                    cursor =\n                        segmentEnd;\n                }\n            }\n\n            if (segments.length === 0) {\n                range.remove();\n                return;\n            }\n\n            if (segments.length > 1) {\n                const replacements = [];\n\n                for (const entry of segments) {\n                    const segment =\n                        document.createElement(\n                            "time-range"\n                        );\n\n                    this.#applyPreservedAttributes(\n                        segment,\n                        preservedAttributes\n                    );\n\n                    this.#copyClockTimerRangeState(\n                        range,\n                        segment\n                    );\n\n                    segment.timeRangeFullEntry =\n                        true;\n\n                    segment.setAttribute(\n                        "ignore-overlaps",\n                        ""\n                    );\n\n                    this.#setRangeTiming(\n                        segment,\n                        entry.start,\n                        entry.end,\n                        preserveRangeLength\n                    );\n\n                    replacements.push({\n                        segment,\n                        ring:\n                            this.#ensureRing(\n                                entry.ringIndex\n                            )\n                    });\n                }\n\n                for (\n                    const {\n                        segment,\n                        ring\n                    } of replacements\n                ) {\n                    ring.appendChild(\n                        segment\n                    );\n                }\n\n                range.remove();\n                return;\n            }\n\n            const entry =\n                segments[0];\n\n            this.#setRangeTiming(\n                range,\n                entry.start,\n                entry.end,\n                preserveRangeLength\n            );\n\n            const ring =\n                this.#ensureRing(\n                    entry.ringIndex\n                );\n\n            if (\n                range.parentElement !== ring\n            ) {\n                const movedSegment =\n                    document.createElement(\n                        "time-range"\n                    );\n\n                this.#applyPreservedAttributes(\n                    movedSegment,\n                    preservedAttributes\n                );\n\n                this.#copyClockTimerRangeState(\n                    range,\n                    movedSegment\n                );\n\n                movedSegment.timeRangeFullEntry =\n                    true;\n\n                movedSegment.setAttribute(\n                    "ignore-overlaps",\n                    ""\n                );\n\n                this.#setRangeTiming(\n                    movedSegment,\n                    entry.start,\n                    entry.end,\n                    preserveRangeLength\n                );\n\n                ring.appendChild(\n                    movedSegment\n                );\n\n                range.remove();\n            }\n        }\n\n'''

path.write_text(text[:start] + replacement + text[end:])
